{
	admin off
	auto_https off
}

http://:{$SMOKE_PORT:8080} {
	bind 127.0.0.1
	map {http.request.host} {consul_service} {
		api.example.test api
		web.example.test web
		default ""
	}
	header >X-Consul-Tier {http.reverse_proxy.upstreams.consul.tier}
	reverse_proxy {
		dynamic consul {
			address {$CONSUL_ADDRESS:http://127.0.0.1:8500}
			service {consul_service}
			refresh 10s
			grace_period 30s
		}
		lb_retries 3
		fail_duration 30s
	}
}
